<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; login_required();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT s.*,u.name cashier,c.gstin customer_gstin,c.address customer_address,c.state_code customer_state FROM sales s JOIN users u ON u.id=s.cashier_id LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=?');$st->execute([$id]);$s=$st->fetch();if(!$s)exit('Invoice not found');if(!can_view_sale($s)){http_response_code(403);exit('Access denied');}
$st=db()->prepare('SELECT si.*,p.sku,p.product_name,p.color,p.size,p.hsn_code,ps.serial_barcode FROM sale_items si JOIN products p ON p.id=si.product_id LEFT JOIN product_serials ps ON ps.id=si.serial_id WHERE si.sale_id=? ORDER BY si.id');$st->execute([$id]);$items=$st->fetchAll();$st=db()->prepare('SELECT mode,amount,reference_no FROM sale_payments WHERE sale_id=? ORDER BY id');$st->execute([$id]);$payments=$st->fetchAll();$company=setting('company_name','Pratyangi Fashions');$gstin=setting('company_gstin','');$address=setting('company_address','');page_header('Invoice '.$s['invoice_no']);?>
<div class="actions no-print"><button class="btn" onclick="print()">Print / Save PDF</button><?php if(is_super_admin()||has_permission('view_reports')):?><a class="btn secondary" href="reports.php">Sales Report</a><?php endif;?></div><br><div class="panel"><h2><?=e($company)?></h2><div class="muted"><?=nl2br(e($address))?><?php if($gstin):?><br>GSTIN: <?=e($gstin)?><?php endif;?></div><hr><div class="row"><div><b>Invoice:</b> <?=e($s['invoice_no'])?><br><b>Date:</b> <?=e($s['created_at'])?><br><b>Cashier:</b> <?=e($s['cashier'])?><br><b>Status:</b> <?=e($s['status'])?></div><div><b>Customer:</b> <?=e($s['customer_name']?:'Walk-in')?><br><b>Mobile:</b> <?=e($s['customer_mobile'])?><?php if($s['customer_gstin']):?><br><b>GSTIN:</b> <?=e($s['customer_gstin'])?><?php endif;?><br><b>Place of Supply:</b> <?=e($s['place_of_supply'])?></div></div><br>
<table><tr><th>Product</th><th>HSN</th><th>Barcode</th><th>Qty</th><th>Rate</th><th>Discount</th><th>Taxable</th><th>GST</th><th>Tax</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['sku'].' · '.$i['product_name'].' '.$i['color'].' '.$i['size'])?></td><td><?=e($i['hsn_code'])?></td><td><?=e($i['serial_barcode']?:$i['barcode'])?></td><td><?=e($i['quantity'])?></td><td>₹<?=e(number_format($i['unit_price'],2))?></td><td>₹<?=e(number_format($i['discount_share'],2))?></td><td>₹<?=e(number_format($i['taxable_value'],2))?></td><td><?=e($i['tax_rate'])?>%</td><td>₹<?=e(number_format($i['tax_amount'],2))?></td></tr><?php endforeach;?></table>
<?php $taxableAfter=max(0,(float)$s['subtotal']-(float)$s['discount_total']); if($s['gst_type']==='IGST'):$igst=(float)$s['tax_total'];?><h3 class="right">Subtotal ₹<?=e(number_format($s['subtotal'],2))?><br>Discount ₹<?=e(number_format($s['discount_total'],2))?><br>Taxable after discount ₹<?=e(number_format($taxableAfter,2))?><br>IGST ₹<?=e(number_format($igst,2))?><br>Grand Total ₹<?=e(number_format($s['grand_total'],2))?></h3><?php else:$half=(float)$s['tax_total']/2;?><h3 class="right">Subtotal ₹<?=e(number_format($s['subtotal'],2))?><br>Discount ₹<?=e(number_format($s['discount_total'],2))?><br>Taxable after discount ₹<?=e(number_format($taxableAfter,2))?><br>CGST ₹<?=e(number_format($half,2))?><br>SGST ₹<?=e(number_format($half,2))?><br>Grand Total ₹<?=e(number_format($s['grand_total'],2))?></h3><?php endif;?>
<?php if((float)($s['refund_total']??0)>0):?><h3 class="right">Refunded ₹<?=e(number_format($s['refund_total'],2))?><br>Net Sale ₹<?=e(number_format(max(0,$s['grand_total']-$s['refund_total']),2))?></h3><?php endif;?>
<?php if($payments):?><h3>Payment</h3><table><tr><th>Mode</th><th>Amount</th><th>Reference</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['mode'])?></td><td>₹<?=e(number_format($p['amount'],2))?></td><td><?=e($p['reference_no'])?></td></tr><?php endforeach;?></table><?php endif;?>
<?php if($s['status']==='CANCELLED'):?><div class="notice error"><b>VOID / CANCELLED:</b> <?=e($s['cancel_reason'])?> · <?=e($s['cancelled_at'])?></div><?php endif;?></div><?php page_footer();
